function plain(x) {
  if (x === null || x === undefined) return x;
  if (Array.isArray(x)) return x.map(plain);
  if (typeof x === 'object') {
    if (typeof x.get === 'function' && x.data && typeof x.data === 'object') return plain(x.data);
    if (Array.isArray(x.items)) return plain(x.items);
    const out = {};
    for (const k of Object.keys(x)) out[k] = plain(x[k]);
    return out;
  }
  return x;
}
const rows = plain(Inputs.items) || [];
const programme = rows[0];
if (!programme) return;
Outputs.projectName = programme.projectName || '';
Outputs.problemStatement = programme.problemStatement || '';
Outputs.endsOn = programme.endsOn || '';
Outputs.entries = programme.entries || [];
/* The objectives the coach and the learner agreed, with the target each was
   agreed at. An ARCHIVED one is still here: its ratings were really given, and
   dropping them would be the chart omitting points without saying so. */
Outputs.dimensions = programme.dimensions || [];
/* WHOSE programme this is, so the coach's page can find their roster row —
   an explicit join rather than a match on the project's name (TASK-L165). */
Outputs.learnerId = programme.learnerId || '';
/* What a HISTORY query returns: the entries of their OTHER programmes, which
   the learner's own page never reads. In the product this is a separate,
   gated fetch the coach makes by choosing a programme (ProgrammeScope.tsx);
   here it is the second half of the same fixture (TASK-L165 §2). */
Outputs.history = programme.history || [];
Outputs.loaded();
